def pairwise_alignment(ref_seq, q_seq):
    aligner = PairwiseAligner()
    aligner.match_score = 1
    aligner.mismatch_score = -1
    aligner.open_gap_score = -4
    aligner.extend_gap_score = -1
    ref_al, q_al = aligner.align(ref_seq.upper(), q_seq.upper())[0]
    return cut_alignment(ref_al, q_al)


def cut_alignment(ref, qry):
    gap_idxs = [i for i, nt in enumerate(ref) if nt == '-']
    return ''.join(nt for i, nt in enumerate(qry) if i not in gap_idxs)


def encode_nt(seq):
    T, F = True, False
    encoding_dict = {
        'A': [T, F, F, F],
        'C': [F, T, F, F],
        'G': [F, F, T, F],
        'T': [F, F, F, T],
        'U': [F, F, F, T],
        'W': [T, F, F, T],
        'S': [F, T, T, F],
        'M': [T, T, F, F],
        'K': [F, F, T, T],
        'R': [T, F, T, F],
        'Y': [F, T, F, T],
        'B': [F, T, T, T],
        'D': [T, F, T, T],
        'H': [T, T, F, T],
        'V': [T, T, T, F],
        'X': [T, T, T, T],
        'N': [T, T, T, T],
        'Z': [F, F, F, F],
        '-': [F, F, F, F]
    }
    encoded_sequence = itertools.chain(*[encoding_dict[base] for base in seq])
    return list(encoded_sequence)


def predict_with_conf(clf, X):
    # scores = clf.decision_function(X)          # shape (n_samples, n_classes)
    probs = clf.predict_proba(X)
    confidence = probs.max(axis=1)            # distance to winning boundary
    labels  = clf.classes_[probs.argmax(axis=1)]
    return (labels, confidence)